import React, { useContext } from 'react';

import { TrackSeparatorLine } from './TrackSeparatorLine.js';
import { MARKER_RADIUS, TestIds, TRACK_HEIGHT } from '../constants.js';
import { AnnotationsContext } from '../context.js';

const getTrackOffset = (index: number) => index * TRACK_HEIGHT;

const getTrackSeparatorOffset = (index: number) => (index + 1) * TRACK_HEIGHT;

interface TracksRendererProps {
  tracks: React.ReactNode;
}

export const TracksRenderer = ({ tracks }: TracksRendererProps) => {
  const { labelsWidth, trackWidth: width } = useContext(AnnotationsContext);

  const trackSeparatorOffset = labelsWidth + MARKER_RADIUS;

  return (
    <>
      <TrackSeparatorLine
        x={trackSeparatorOffset}
        width={width}
        y={0}
      ></TrackSeparatorLine>
      {React.Children.map(tracks, (track, index) => (
        <>
          <g
            transform={`translate(0,${getTrackOffset(index)})`}
            data-testid={`${TestIds.Track}-${index}`}
          >
            {track}
          </g>

          <TrackSeparatorLine
            x={trackSeparatorOffset}
            width={width}
            y={getTrackSeparatorOffset(index)}
          ></TrackSeparatorLine>
        </>
      ))}
    </>
  );
};

TracksRenderer['displayName'] = 'Annotations.TracksRenderer';
